class Solution { public: int minimumOperationsToWriteY(vector<vector<int>>& grid) {
 int n=grid.size(), c[2][3]={};
 for(int i=0;i<n;i++) for(int j=0;j<n;j++) {
  bool y=(i<=n/2&&(j==i||j==n-1-i))||(i>n/2&&j==n/2);
  ++c[y][grid[i][j]];
 }
 int ans=n*n;
 for(int a=0;a<3;a++) for(int b=0;b<3;b++) if(a!=b) {
  int cost=0; for(int x=0;x<3;x++) {if(x!=a) cost+=c[1][x]; if(x!=b) cost+=c[0][x];}
  ans=min(ans,cost);
 } return ans;
}};
